export interface IconDefinition {
  /** SVG viewBox，同時決定圖示的原生尺寸 */
  viewBox: string;
  /** Figma 中的描邊寬度（viewBox 單位，會隨顯示尺寸等比縮放）；填色圖示為 0 */
  strokeWidth: number;
  /** 上色方式：描邊（Lucide 系列）或填色（Search Bar 的放大鏡） */
  mode: 'stroke' | 'fill';
  /** 原生尺寸（px）—— 未指定 size 時的預設值 */
  size: number;
  /** 對應的 Figma 元件，方便追溯來源 */
  figma: { name: string; nodeId: string };
  /** SVG 內容 */
  body: string;
}

